-- ===================================================================
-- 0009_leaders.sql
-- ===================================================================
-- Church leaders, added by FUJ admins (leaders don't sign up themselves).
-- Each leader is linked to a person record (name, WhatsApp/phone number, email), so broadcasts to
-- "All leaders" or one unit's leaders use the same WhatsApp / SMS / email / in-app delivery and tracking.
-- Idempotent: safe to run more than once.

create table if not exists public.leaders (
  id uuid primary key default gen_random_uuid(),
  person_id uuid not null references public.people(id) on delete cascade,
  unit text not null check (length(trim(unit)) > 0),
  added_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint leaders_person_unique unique (person_id)
);
create index if not exists leaders_unit_idx on public.leaders (lower(unit));

-- Only the server (service-role key) reads or writes leaders; no direct client access.
alter table public.leaders enable row level security;

notify pgrst, 'reload schema';

-- ===================================================================
-- 0010_everyone_is_a_member.sql
-- ===================================================================
-- FUJ has no "visitor" category and no verification step: everyone who registers is a member,
-- verified automatically at sign-up. Idempotent: safe to run more than once.

-- 1. Existing visitors become members (joined when they first registered).
update public.people
set status = 'member', joined_at = coalesce(joined_at, first_visit_at, created_at), updated_at = now()
where status = 'visitor';
alter table public.people alter column status set default 'member';
-- The enum value can't be dropped safely, so stop it being used again.
do $$ begin
  alter table public.people add constraint people_no_visitor_status check (status <> 'visitor');
exception when duplicate_object then null; end $$;

-- 2. Everyone counts as verified from their first sign-in.
alter table public.people drop constraint if exists people_verified_via_valid;
alter table public.people add constraint people_verified_via_valid
  check (verified_via is null or verified_via in ('google','in_person','admin','otp','registration'));
update public.people
set verified_via = 'registration', verified_at = coalesce(verified_at, created_at)
where verified_via is null;

notify pgrst, 'reload schema';

-- ===================================================================
-- 0011_auto_follow_up.sql
-- ===================================================================
-- Automatic absence follow-up: when a member misses N consecutive Sundays (absence_threshold) they get a
-- message on the chosen channels, then a reminder every follow_up_every_days days until they come back
-- (or staff close their follow-up task). Idempotent: safe to run more than once.

alter table public.church_settings add column if not exists auto_follow_up boolean not null default true;
alter table public.church_settings add column if not exists follow_up_every_days integer not null default 3
  check (follow_up_every_days between 1 and 30);
-- 0 = keep reminding until they come back.
alter table public.church_settings add column if not exists follow_up_max_messages integer not null default 0
  check (follow_up_max_messages between 0 and 100);
alter table public.church_settings add column if not exists follow_up_channels text[] not null default array['whatsapp','sms','email'];
alter table public.church_settings add column if not exists follow_up_first_message text;
alter table public.church_settings add column if not exists follow_up_reminder_message text;

alter table public.follow_up_tasks add column if not exists auto_messages_sent integer not null default 0;
alter table public.follow_up_tasks add column if not exists last_auto_message_at timestamptz;
create index if not exists follow_up_tasks_open_absentee_idx on public.follow_up_tasks (category, status);

notify pgrst, 'reload schema';

-- ===================================================================
-- 0012_first_timers_and_partners.sql
-- ===================================================================
-- First timers and FUJ Partners — two follow-up workflows of their own.
--  * At registration people say whether this is their FIRST TIME at FlagUpJesus (an old member can register
--    online any day, so "new on the website" no longer means "new to church"). First timers get a journey:
--    new → welcomed (someone reached them) → returned (came back to church) → settled (joined a unit / regular),
--    or closed. A welcome message goes out straight away and, until they come back, an invitation every Saturday.
--  * People can ask to become FUJ PARTNERS (regular giving to support the ministry). Partners move through
--    interested → contacted → committed (pledged) → active (giving), or paused / declined, with pledges,
--    follow-up dates, giving history and optional monthly reminders.
-- Idempotent: safe to run more than once.

-- What the person told us at registration (null = not asked, e.g. added by an usher before this existed).
alter table public.people add column if not exists first_timer boolean;

create table if not exists public.first_timers (
  id uuid primary key default gen_random_uuid(),
  person_id uuid not null references public.people(id) on delete cascade,
  first_visit_at timestamptz not null default now(),
  service_id uuid references public.services(id) on delete set null,
  stage text not null default 'new' check (stage in ('new','welcomed','returned','settled','closed')),
  source text not null default 'registration' check (source in ('registration','desk','admin')),
  assignee text,
  visits integer not null default 1,
  welcome_sent_at timestamptz,
  invites_sent integer not null default 0,
  last_invite_at timestamptz,
  welcomed_at timestamptz,
  returned_at timestamptz,
  settled_at timestamptz,
  closed_at timestamptz,
  close_reason text,
  last_contacted_at timestamptz,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint first_timers_person_unique unique (person_id)
);
create index if not exists first_timers_stage_idx on public.first_timers (stage);

create table if not exists public.partners (
  id uuid primary key default gen_random_uuid(),
  person_id uuid not null references public.people(id) on delete cascade,
  status text not null default 'interested' check (status in ('interested','contacted','committed','active','paused','declined')),
  source text not null default 'registration' check (source in ('registration','portal','admin')),
  pledge_amount numeric(14,2) check (pledge_amount is null or pledge_amount >= 0),
  frequency text check (frequency is null or frequency in ('monthly','quarterly','yearly','one_off')),
  assignee text,
  next_follow_up_at timestamptz,
  last_contacted_at timestamptz,
  last_gift_at timestamptz,
  thanks_sent_at timestamptz,
  last_reminder_at timestamptz,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint partners_person_unique unique (person_id)
);
create index if not exists partners_status_idx on public.partners (status);

-- Calls, WhatsApps, visits and automatic messages logged against a first timer or a partner.
create table if not exists public.contact_logs (
  id uuid primary key default gen_random_uuid(),
  subject text not null check (subject in ('first_timer','partner')),
  subject_id uuid not null,
  channel text not null check (channel in ('call','sms','whatsapp','visit','email','in_app','note')),
  outcome text not null,
  note text,
  author text,
  created_at timestamptz not null default now()
);
create index if not exists contact_logs_subject_idx on public.contact_logs (subject, subject_id, created_at desc);

-- Automatic messages (sent on the same channels as the absence follow-up).
alter table public.church_settings add column if not exists first_timer_auto boolean not null default true;
alter table public.church_settings add column if not exists first_timer_max_invites integer not null default 3
  check (first_timer_max_invites between 0 and 8);
alter table public.church_settings add column if not exists first_timer_welcome_message text;
alter table public.church_settings add column if not exists first_timer_invite_message text;
alter table public.church_settings add column if not exists partner_auto boolean not null default true;
alter table public.church_settings add column if not exists partner_reminders boolean not null default false;
alter table public.church_settings add column if not exists partner_reminder_day integer not null default 1
  check (partner_reminder_day between 1 and 28);
alter table public.church_settings add column if not exists partner_thanks_message text;
alter table public.church_settings add column if not exists partner_reminder_message text;

-- Only the server (service-role key) reads or writes these; no direct client access.
alter table public.first_timers enable row level security;
alter table public.partners enable row level security;
alter table public.contact_logs enable row level security;

notify pgrst, 'reload schema';

-- ===================================================================
-- 0013_children.sql
-- ===================================================================
-- Children's registration. Children who don't have a phone of their own register with a parent's or guardian's
-- number: they get their own record and flag username (for check-in and attendance), linked to the parent when
-- the parent is — or later becomes — a registered member with that number. Phone numbers therefore stay unique
-- among adults only. Children receive messages in the app only; WhatsApp / SMS / email go to the parent.
-- Idempotent: safe to run more than once.

alter table public.people add column if not exists is_child boolean not null default false;
alter table public.people add column if not exists guardian_id uuid references public.people(id) on delete set null;
alter table public.people add column if not exists guardian_name text;
alter table public.people add column if not exists guardian_relationship text;
-- Allergies, medical or special-care needs (children's church only).
alter table public.people add column if not exists care_notes text;
create index if not exists people_guardian_idx on public.people (guardian_id);

-- One phone number per adult; children share their parent's number.
-- Once 0015 has replaced this rule with people_phone_owner_key (family members may share a number too),
-- it must not come back on a re-run: shared family numbers would make it fail.
alter table public.people drop constraint if exists people_normalized_phone_key;
do $$ begin
  if not exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'people_phone_owner_key') then
    create unique index if not exists people_adult_phone_key on public.people (normalized_phone) where not is_child;
  end if;
end $$;
create index if not exists people_phone_idx on public.people (normalized_phone);

notify pgrst, 'reload schema';

-- ===================================================================
-- 0014_welcome_email_and_passwords.sql
-- ===================================================================
-- Welcome email + optional member passwords.
--  * Everyone with an email address gets a warm "Welcome to FlagUpJesus Global Connect" email with their flag username —
--    new registrations straight away, people who registered earlier through Settings → Welcome emails or the
--    daily job. welcome_email_sent_at records when it went out.
--  * The email has a link to set a password, so members can sign in with username (or email) + password as well as
--    username + phone. Password hashes live in their own table with no client access (people rows can be read by
--    the member they belong to).
-- Idempotent: safe to run more than once.

alter table public.people add column if not exists welcome_email_sent_at timestamptz;

create table if not exists public.member_credentials (
  person_id uuid primary key references public.people(id) on delete cascade,
  password_hash text not null,
  updated_at timestamptz not null default now()
);
alter table public.member_credentials enable row level security;

notify pgrst, 'reload schema';

-- ===================================================================
-- 0015_shared_phones.sql
-- ===================================================================
-- Family members who share one phone number (e.g. a couple with one phone). Like children on a parent's number,
-- an adult can now use another member's number: their own record and username, linked to the person whose number
-- it is (guardian_id), with WhatsApp / SMS / email going to that person once. Used by contact imports where a
-- list has several people on one number. Idempotent: safe to run more than once.

alter table public.people add column if not exists shares_phone boolean not null default false;

-- One phone number per "owner"; children and family members sharing it are allowed.
drop index if exists public.people_adult_phone_key;
create unique index if not exists people_phone_owner_key on public.people (normalized_phone) where not is_child and not shares_phone;

notify pgrst, 'reload schema';

